//#region ../send/frontend/src/apps/send/composables/useUploadAndShare.ts
function useUploadAndShare() {
	const folderStore = useFolderStore();
	const sharingStore = useSharingStore();
	const { api } = useApiStore();
	const { keychain } = useKeychainStore();
	const isUploading = /* @__PURE__ */ ref(false);
	const isError = /* @__PURE__ */ ref(false);
	const uploadMap = /* @__PURE__ */ ref(/* @__PURE__ */ new Map());
	async function uploadAndShare(files, password, expiration, onStatusUpdate) {
		if (keychain.locked) {
			isError.value = true;
			throw new Error("Cannot upload: encryption keys are locked. Please re-enter your passphrase.");
		}
		isUploading.value = true;
		isError.value = false;
		const uploadedItems = [];
		const rootFolderId = await folderStore.getDefaultFolderId();
		for (let i = 0; i < files.length; i++) {
			const file = files[i];
			try {
				if (onStatusUpdate) onStatusUpdate(i, "uploading");
				const itemObjArray = await folderStore.uploadItem(file.data, rootFolderId, api);
				if (!itemObjArray || itemObjArray?.length === 0) throw new Error(`Could not upload file ${file.name}`);
				console.log(`[uploadAndShare] Successfully uploaded ${file.name}`);
				for (const itemObj of itemObjArray) {
					uploadedItems.push({
						originalId: file.id,
						...itemObj
					});
					uploadMap.value.set(file.id, true);
				}
				if (onStatusUpdate) onStatusUpdate(i, "completed");
			} catch (err) {
				console.log(err);
				if (onStatusUpdate) onStatusUpdate(i, "error");
				uploadAborted();
				isError.value = true;
				isUploading.value = false;
				throw err;
			}
		}
		try {
			const organizedFiles = organizeFiles(uploadedItems);
			const url = await sharingStore.shareItems(organizedFiles, password, expiration);
			if (!url) throw new Error(`Did not get URL back from sharingStore`);
			console.log(`I got a sharing url and it is`);
			console.log(url);
			shareComplete(url, [...uploadedItems]);
		} catch (err) {
			console.log(err.message);
			shareAborted();
			isError.value = true;
			isUploading.value = false;
			throw err;
		}
	}
	function shareComplete(url, results) {
		browser.runtime.sendMessage({
			type: ALL_UPLOADS_COMPLETE,
			url,
			results,
			aborted: false
		});
		window.close();
	}
	function uploadAborted() {
		browser.runtime.sendMessage({
			type: ALL_UPLOADS_ABORTED,
			aborted: true
		});
	}
	function shareAborted() {
		browser.runtime.sendMessage({
			type: ALL_UPLOADS_ABORTED,
			aborted: true
		});
		window.close();
	}
	return {
		isUploading,
		isError,
		uploadMap,
		uploadAndShare
	};
}
//#endregion
